private ByteTransition findNextByteStateForRangePattern(ByteTransition trans, final byte b) {
    if (trans == null) {
        return null;
    }
    ByteTransition nextTrans = getTransition(trans, b);
    return nextTrans.getTransitionForNextByteStates();
}
